package dev.mineagent.runtime.neoforge.ui;
import com.fasterxml.jackson.databind.*;import dev.mineagent.runtime.core.interaction.InteractionRuleSpec;import dev.mineagent.runtime.neoforge.MineAgentRuntimeServices;import dev.mineagent.runtime.api.config.ConfigPatch;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.Entity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.InteractionResult;import net.neoforged.bus.api.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.entity.player.*;import java.util.*;
/** Synchronous native before-interaction rules, not cosmetic lock messages or block substitutions. */
@EventBusSubscriber(modid="mineagent_runtime")
public final class ServerInteractionRules {
 private static final ObjectMapper JSON=new ObjectMapper();public record Saved(UUID id,UUID owner,long revision,String source){}
 private static final Map<MinecraftServer,Cache> CACHES=new WeakHashMap<>();private static final ThreadLocal<Boolean> CALLBACK=ThreadLocal.withInitial(()->false);
 private static final class Cache{long configRevision=-1;final Map<UUID,Saved> rules=new LinkedHashMap<>();final Map<UUID,InteractionRuleSpec> specs=new HashMap<>();final Map<String,Long> last=new HashMap<>();final Map<UUID,long[]> counts=new HashMap<>();}
 private static String prefix(MinecraftServer s){return "interaction.rules."+MineAgentRuntimeServices.worldId(s)+".";}
 private static Cache cache(MinecraftServer s){var c=CACHES.computeIfAbsent(s,k->new Cache());var snap=MineAgentRuntimeServices.config(s).snapshot();if(snap.revision()!=c.configRevision){c.rules.clear();c.specs.clear();for(var entry:snap.values().entrySet())if(entry.getKey().startsWith(prefix(s))&&!entry.getValue().isBlank())try{var rule=JSON.readValue(entry.getValue(),Saved.class);c.rules.put(rule.id(),rule);c.specs.put(rule.id(),InteractionRuleSpec.parse(rule.source()));}catch(Exception e){throw new IllegalStateException("INTERACTION_RULE_STATE_INVALID",e);}c.configRevision=snap.revision();}return c;}
 public static Map<String,Object> inspect(ServerPlayer p,int offset){if(offset<0)throw new IllegalArgumentException("INTERACTION_OFFSET");var c=cache(p.level().getServer());var list=c.rules.values().stream().filter(r->r.owner().equals(p.getUUID())).toList();var items=list.stream().skip(offset).limit(16).map(r->Map.of("rule",r,"cancelled",c.counts.getOrDefault(r.id(),new long[2])[0],"continued",c.counts.getOrDefault(r.id(),new long[2])[1])).toList();return Map.of("rules",items,"nextOffset",offset+16<list.size()?offset+16:-1,"contract","set_interaction_rule creates/updates/removes native callback rules; target position OR entity_id, events block_use/block_break/entity_use/entity_attack, decision cancel/continue; optional key_item or key_instance+key_part, allow_players; on_denied/on_allowed arrays {type:message|sound|command,value:string}. Command callbacks run only for the rule creator, with their current permissions; other players never lend command authority. Door halves normalize to lower block. Does not block redstone/automation that has no player event. No rule grants an otherwise denied Mod interaction.");}
 public static Map<String,Object> set(ServerPlayer p,UUID operation,JsonNode a,boolean remove)throws Exception{if(!p.permissions().hasPermission(net.minecraft.server.permissions.Permissions.COMMANDS_GAMEMASTER))throw new SecurityException("INTERACTION_GAMEMASTER_REQUIRED");if(a.has("expected_revision")&&(!a.get("expected_revision").isIntegralNumber()||!a.get("expected_revision").canConvertToLong()||a.get("expected_revision").longValue()<0||a.get("expected_revision").longValue()==Long.MAX_VALUE))throw new IllegalArgumentException("INTERACTION_RULE_REVISION");var s=p.level().getServer();var c=cache(s);UUID id=a.has("rule_id")?UUID.fromString(a.path("rule_id").asText()):operation;Saved old=c.rules.get(id);long expected=a.path("expected_revision").asLong(0);if(old!=null&&!old.owner().equals(p.getUUID()))throw new SecurityException("INTERACTION_RULE_NOT_OWNED");if((old==null?0:old.revision())!=expected||remove&&old==null)throw new IllegalStateException("INTERACTION_RULE_STALE");if(old==null&&c.rules.size()>=512)throw new IllegalStateException("INTERACTION_RULE_CAPACITY");String value="";if(!remove){var spec=InteractionRuleSpec.parse(a.path("source").asText());if(!spec.keyItem().isEmpty()&&!net.minecraft.core.registries.BuiltInRegistries.ITEM.containsKey(net.minecraft.resources.Identifier.parse(spec.keyItem())))throw new IllegalArgumentException("INTERACTION_RULE_UNKNOWN_KEY");for(var list:List.of(spec.allowedActions(),spec.deniedActions()))for(var action:list)if(action.get("type").equals("sound")&&!net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.containsKey(net.minecraft.resources.Identifier.parse(action.get("value"))))throw new IllegalArgumentException("INTERACTION_RULE_SOUND_UNKNOWN");if(!spec.dimension().equals(p.level().dimension().identifier().toString()))throw new IllegalArgumentException("INTERACTION_RULE_DIMENSION");if(!spec.position().isEmpty()){var pos=new BlockPos(spec.position().get(0),spec.position().get(1),spec.position().get(2));if(!p.level().hasChunkAt(pos)||p.level().isOutsideBuildHeight(pos)||!p.level().getWorldBorder().isWithinBounds(pos))throw new IllegalArgumentException("INTERACTION_RULE_TARGET_NOT_LOCAL");}else if(p.level().getEntity(UUID.fromString(spec.entityId()))==null)throw new IllegalArgumentException("INTERACTION_RULE_ENTITY_UNLOADED");if(!spec.position().isEmpty()){var target=new BlockPos(spec.position().get(0),spec.position().get(1),spec.position().get(2));var normalized=normalize(p,target);if(!normalized.equals(target)){var source=(com.fasterxml.jackson.databind.node.ObjectNode)JSON.readTree(spec.source());source.putArray("position").add(normalized.getX()).add(normalized.getY()).add(normalized.getZ());spec=InteractionRuleSpec.parse(source.toString());}}value=JSON.writeValueAsString(new Saved(id,p.getUUID(),expected+1,spec.source()));}var config=MineAgentRuntimeServices.config(s);var r=config.apply(new ConfigPatch(config.snapshot().revision(),Map.of(prefix(s)+id,value)),true);if(!r.accepted())throw new IllegalStateException(r.errorCode());return Map.of("status",remove?"REMOVED":"APPLIED","ruleId",id,"revision",expected+1,"nativeCallback",true);}
 private static BlockPos normalize(ServerPlayer p,BlockPos pos){var state=p.level().getBlockState(pos);if(state.getBlock() instanceof net.minecraft.world.level.block.DoorBlock&&state.getValue(net.minecraft.world.level.block.DoorBlock.HALF)==net.minecraft.world.level.block.state.properties.DoubleBlockHalf.UPPER){var below=p.level().getBlockState(pos.below());if(below.getBlock()==state.getBlock()&&below.getValue(net.minecraft.world.level.block.DoorBlock.HALF)==net.minecraft.world.level.block.state.properties.DoubleBlockHalf.LOWER)return pos.below();}if(state.getBlock() instanceof net.minecraft.world.level.block.ChestBlock&&state.getValue(net.minecraft.world.level.block.ChestBlock.TYPE)!=net.minecraft.world.level.block.state.properties.ChestType.SINGLE){var other=pos.relative(net.minecraft.world.level.block.ChestBlock.getConnectedDirection(state));var neighbor=p.level().getBlockState(other);if(neighbor.getBlock()==state.getBlock()&&neighbor.getValue(net.minecraft.world.level.block.ChestBlock.TYPE)!=net.minecraft.world.level.block.state.properties.ChestType.SINGLE&&neighbor.getValue(net.minecraft.world.level.block.ChestBlock.TYPE)!=state.getValue(net.minecraft.world.level.block.ChestBlock.TYPE)&&neighbor.getValue(net.minecraft.world.level.block.ChestBlock.FACING)==state.getValue(net.minecraft.world.level.block.ChestBlock.FACING)&&other.relative(net.minecraft.world.level.block.ChestBlock.getConnectedDirection(neighbor)).equals(pos))return pos.compareTo(other)<0?pos:other;}return pos;}
 private static boolean key(ServerPlayer p,InteractionRuleSpec spec){for(ItemStack stack:List.of(p.getMainHandItem(),p.getOffhandItem())){if(stack.isEmpty())continue;boolean item=spec.keyItem().isEmpty()||net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString().equals(spec.keyItem());var binding=dev.mineagent.runtime.neoforge.content.RuntimeItem.binding(stack);boolean custom=spec.keyInstance().isEmpty()||binding!=null&&binding.world().equals(MineAgentRuntimeServices.worldId(p.level().getServer()))&&binding.instance().toString().equals(spec.keyInstance())&&(spec.keyPart().isEmpty()||binding.part().equals(spec.keyPart()));if(item&&custom&&(!spec.keyItem().isEmpty()||!spec.keyInstance().isEmpty()))return true;}return false;}
 public static boolean denied(ServerPlayer p,BlockPos pos,Entity entity,String event,boolean execute){if(CALLBACK.get()||!dev.mineagent.runtime.neoforge.WorldIdentityRuntime.ready(p.level().getServer()))return false;var c=cache(p.level().getServer());boolean denied=false;var target=pos==null?null:normalize(p,pos);for(var entry:c.rules.entrySet()){var spec=c.specs.get(entry.getKey());if(!spec.dimension().equals(p.level().dimension().identifier().toString())||!spec.events().contains(event))continue;if(target!=null){if(spec.position().isEmpty()||!target.equals(new BlockPos(spec.position().get(0),spec.position().get(1),spec.position().get(2))))continue;}else if(entity==null||!entity.getUUID().toString().equals(spec.entityId()))continue;boolean blocked=spec.decision().equals("cancel")&&!spec.allow().contains(p.getUUID())&&!key(p,spec);denied|=blocked;if(execute){String dedup=entry.getKey()+":"+p.getUUID()+":"+event;long tick=p.level().getGameTime();if(c.last.getOrDefault(dedup,Long.MIN_VALUE)==tick)continue;c.last.put(dedup,tick);if(c.last.size()>4096)c.last.entrySet().removeIf(v->tick-v.getValue()>100);c.counts.computeIfAbsent(entry.getKey(),k->new long[2])[blocked?0:1]++;if(blocked)p.sendSystemMessage(Component.literal("["+spec.name()+"] 已阻止交互。"));CALLBACK.set(true);try{for(var action:blocked?spec.deniedActions():spec.allowedActions())switch(action.get("type")){case "message"->p.sendSystemMessage(Component.literal(action.get("value")));case "sound"->{var id=net.minecraft.resources.Identifier.tryParse(action.get("value"));var sound=id==null?null:net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.getValue(id);if(sound!=null)p.level().playSound(null,p.blockPosition(),sound,net.minecraft.sounds.SoundSource.BLOCKS,1,1);}case "command"->{if(p.getUUID().equals(entry.getValue().owner()))p.level().getServer().getCommands().performPrefixedCommand(p.createCommandSourceStack(),action.get("value"));}}}finally{CALLBACK.remove();}}}return denied;}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void block(PlayerInteractEvent.RightClickBlock e){if(e.getEntity() instanceof ServerPlayer p&&denied(p,e.getPos(),null,"block_use",true)){e.setCanceled(true);e.setCancellationResult(InteractionResult.FAIL);p.connection.send(new net.minecraft.network.protocol.game.ClientboundBlockUpdatePacket(p.level(),e.getPos()));p.connection.send(new net.minecraft.network.protocol.game.ClientboundBlockUpdatePacket(p.level(),e.getPos().above()));p.connection.send(new net.minecraft.network.protocol.game.ClientboundBlockUpdatePacket(p.level(),e.getPos().below()));}}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void dig(PlayerInteractEvent.LeftClickBlock e){if(e.getEntity() instanceof ServerPlayer p&&denied(p,e.getPos(),null,"block_break",true))e.setCanceled(true);}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void breaking(net.neoforged.neoforge.event.level.block.BreakBlockEvent e){if(e.getPlayer() instanceof ServerPlayer p&&denied(p,e.getPos(),null,"block_break",true)){e.setCanceled(true);e.setNotifyClient(true);}}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void entity(PlayerInteractEvent.EntityInteract e){if(e.getEntity() instanceof ServerPlayer p&&denied(p,null,e.getTarget(),"entity_use",true)){e.setCanceled(true);e.setCancellationResult(InteractionResult.FAIL);}}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void entityAt(PlayerInteractEvent.EntityInteractSpecific e){if(e.getEntity() instanceof ServerPlayer p&&denied(p,null,e.getTarget(),"entity_use",true)){e.setCanceled(true);e.setCancellationResult(InteractionResult.FAIL);}}
 @SubscribeEvent(priority=EventPriority.HIGHEST) public static void attack(AttackEntityEvent e){if(e.getEntity() instanceof ServerPlayer p&&denied(p,null,e.getTarget(),"entity_attack",true))e.setCanceled(true);}
 private ServerInteractionRules(){}
}
